import {moneyDisplay,allowedReturnPath,FILE_TYPES,AI_TASKS} from './domain/contracts.mjs';
import {AD_CHANNELS,adChannel} from './domain/channels.mjs';
const app=document.querySelector('#app');
const state={user:null,csrf:null,businesses:[],invitations:[],workspace:null,error:null,notice:null,busy:false,loginStep:'email',returnPath:'/workspace/',mfa:null};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=value=>String(value??'').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const org=()=>new URL(location.href).searchParams.get('business')||state.businesses[0]?.id;
const path=()=>location.pathname.split('/').filter(Boolean);
const isOperator=()=>Boolean(state.workspace?.viewer.operator);
const rows=key=>state.workspace?.[key]||[];
const name=id=>rows('people').find(x=>x.id===id)?.name||(id===state.user?.id?'You':'Studio');
const date=value=>value?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:state.workspace?.business.timezone||'America/New_York'}).format(new Date(value)):'Not yet scheduled';
const dateTime=value=>value?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:state.workspace?.business.timezone||'America/New_York',timeZoneName:'short'}).format(new Date(value)):'Not yet confirmed';
const engagement=id=>rows('engagements').find(x=>x.id===id);
const href=(section='',id='',owner=false)=>`${owner?'/operator/':'/workspace/'}${section}${id?'/'+id:''}?business=${encodeURIComponent(org()||'')}`;
const link=(section,title,id='',cls='')=>`<a class="${cls}" href="${href(section,id)}" data-nav>${esc(title)}</a>`;
const badge=value=>`<span class="status ${['unknown','failed','attention','changes_requested','unconfirmed'].includes(value)?'attention':['in_review','waiting','pending','requested','observed_pending','setup','unverified'].includes(value)?'warning':['closed','cancelled'].includes(value)?'neutral':''}">${esc(label(value))}</span>`;
const empty=(title,copy)=>`<div class="empty"><div class="empty-mark" aria-hidden="true">○</div><h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`;
const brand=()=>'<a class="brand" href="/workspace/" data-nav><span class="brand-symbol" aria-hidden="true">w.</span><strong>Wonder and Method<small>Your working space</small></strong></a>';
const field=(title,name,value='',type='text',extra='')=>`<label>${esc(title)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(title,name,value='',extra='')=>`<label>${esc(title)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(title,name,options,value='',extra='')=>`<label>${esc(title)}<select name="${name}" ${extra}>${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const hidden=(key,value)=>`<input type="hidden" name="${key}" value="${esc(value)}">`;
const submit=(text='Save')=>`<button class="button" type="submit" ${state.busy?'disabled':''}>${state.busy?'Saving…':esc(text)}</button>`;
const serviceSelect=(value='')=>select('Service','engagement_id',rows('engagements').filter(x=>x.service_state!=='closed').map(x=>[x.id,x.title]),value,'required');
const alert=()=>`${state.error?`<div class="alert" role="alert" tabindex="-1">${esc(state.error)}</div>`:''}${state.notice?`<div class="success" role="status">${esc(state.notice)}</div>`:''}`;
function navigate(url){history.pushState({},'',url);state.error=null;state.notice=null;render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
async function api(url,{method='GET',data,key,retry=true}={}){
  const response=await fetch(url,{method,credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json','X-CSRF-Token':state.csrf}:{}),...(key?{'Idempotency-Key':key}:{})},...(data?{body:JSON.stringify(data)}:{})});
  const result=await response.json().catch(()=>({}));
  if(response.status===401&&state.user&&retry&&!url.startsWith('/api/auth/')){
    const refreshed=await api('/api/auth/refresh',{method:'POST',data:{},retry:false});state.csrf=refreshed.csrf;
    return api(url,{method,data,key,retry:false});
  }
  if(!response.ok){const error=new Error(result.error?.message||'This request could not be completed.');error.code=result.error?.code;throw error;}return result;
}
async function loadWorkspace(){
  [state.businesses,state.invitations]=await Promise.all([api('/api/businesses'),api('/api/invitations')]);
  const id=org();state.workspace=id?await api(`/api/workspace?business=${encodeURIComponent(id)}`):null;
}
async function command(name,input,key){return api('/api/command',{method:'POST',data:{organization_id:org(),command:name,input},key});}
function authView(){
  const code=state.loginStep==='code';
  return `<main id="main" class="auth">${brand()}<p class="eyebrow">A little less back-and-forth</p><h1 tabindex="-1">Your work, all together.</h1><p class="muted">Requests, decisions, and the next clear step for your business.</p>${alert()}<section class="panel"><h2>${code?'Check your email':'Sign in to your workspace'}</h2><form data-action="${code?'verify':'login'}">${code?field('Email sign-in code','code','','text','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" maxlength="10"'):field('Email address','email','','email','required autocomplete="email"')}<p class="form-help">${code?'Enter the code from your email. It works once and expires shortly.':'Use the email address invited to your business workspace.'}</p>${submit(code?'Open my workspace':'Email me a sign-in code')}</form>${code?'<button class="text-button" data-action="restart-login">Use a different email or request a new code</button>':''}</section><p class="foot">Your sign-in identifies you. Each business controls which work and decisions you can access.</p></main>`;
}
function shell(content){
  const section=path()[1]||'home',owner=path()[0]==='operator';const pending=rows('requests').filter(x=>x.state==='in_review').length;
  const nav=[['home','Overview'],['work','Your work'],['approvals','To review'],['messages','Messages'],['files','Files'],['ads','Advertising'],['results','Results'],['business','Business details'],['billing','Billing'],['people','People & access'],['help','Help']];
  return `<div class="app-shell"><aside class="sidebar">${brand()}<label class="business-select">Your business<select id="business-selector" aria-label="Choose a business">${state.businesses.map(b=>`<option value="${b.id}" ${b.id===org()?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><nav class="nav" aria-label="Workspace">${nav.map(([key,title])=>`<a href="${href(key==='home'?'':key)}" data-nav ${section===key&&!owner?'aria-current="page"':''}><span>${title}</span>${key==='approvals'&&pending?`<span class="count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom">${isOperator()?`<a class="operator-switch" href="${href('queue','',true)}" data-nav>Studio workspace ↗</a>`:''}<p>Clear steps. Considered work.<br>A little room to breathe.</p></div></aside><div class="content"><header class="topbar"><span class="context">${esc(state.workspace?.business.name||'Your businesses')} / ${owner?'Studio':esc(nav.find(x=>x[0]===section)?.[1]||'Your work')}</span><div class="identity"><span class="email">${esc(state.user.email)}</span><span class="avatar" aria-hidden="true">${esc((state.user.email||'Y')[0].toUpperCase())}</span><button class="text-button" data-action="logout">Sign out</button></div></header><main id="main" class="page">${alert()}${content}<p class="footer-note">Dates shown in ${esc(state.workspace?.business.timezone||'America/New_York')}. Last refreshed ${dateTime(new Date().toISOString())}.</p></main></div></div>`;
}
function heading(kicker,title,copy,action=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1 tabindex="-1">${esc(title)}</h1><p class="muted">${esc(copy)}</p></div>${action}</div>`;}
function requestRows(list){return list.length?`<ul class="rows">${list.map(r=>`<li class="row"><div class="row-main"><strong>${link('work',r.outcome,r.id)}</strong><p>${esc(engagement(r.engagement_id)?.title)} · ${r.due_at?'Due '+date(r.due_at):'Timing to be agreed'}</p></div>${badge(r.state)}</li>`).join('')}</ul>`:empty('Nothing waiting here','New requests and updates will appear here when there is work to do.');}
function homeView(){
  const needs=rows('requests').filter(x=>x.state==='in_review'),active=rows('requests').filter(x=>!['complete'].includes(x.state));
  return heading('Your workspace','Good work starts with a clear next step.','See what needs you, what we’re working on, and what’s coming next.',link('new','＋ Make a request','','button'))+
    `<section class="hero"><div><p class="eyebrow">${needs.length?'A decision for you':'One place to move things forward'}</p><h2>${needs.length?`${needs.length} ${needs.length===1?'item is':'items are'} ready for your review.`:'What would you like to make better?'}</h2><p>${needs.length?'Review the exact work, cost, and timing before giving your approval.':'Tell us the outcome you want. We’ll confirm what’s included, who will do it, and when you can expect it.'}</p></div>${link(needs.length?'approvals':'new',needs.length?'Review the work →':'Start a request →','','button')}</section>
    <div class="grid metrics"><section class="card"><span class="label">Work in progress</span><strong class="metric">${active.length}</strong><span class="label">Across your services</span></section><section class="card"><span class="label">Waiting for your review</span><strong class="metric">${needs.length}</strong><span class="label">Your decisions stay on record</span></section><section class="card"><span class="label">Active services</span><strong class="metric">${rows('engagements').filter(x=>x.service_state==='active').length}</strong><span class="label">${rows('engagements').filter(x=>x.service_state==='setup').length} in setup</span></section></div>
    <div class="grid two"><section class="panel"><div class="panel-heading"><h2>Moving forward</h2>${link('work','View all →')}</div>${requestRows(active.slice(0,5))}</section><section class="panel"><h2>Coming up</h2>${rows('commitments').filter(x=>!['delivered','cancelled'].includes(x.status)).slice(0,4).map(x=>`<div class="row"><div class="row-main"><strong>${esc(x.deliverable)}</strong><p>${date(x.due_at)} · ${esc(name(x.owner_user_id))}</p><p>Next update ${date(x.next_update_at)}</p></div></div>`).join('')||empty('No dates to keep track of yet','Once work is accepted, your next delivery and update dates will be shown here.')}</section></div>`;
}
function newRequestView(){return heading('Start with the outcome','What do you need?','A sentence is enough to get started. We’ll confirm scope, price, and timing before work begins.')+`<section class="panel narrow">${rows('engagements').length?`<form data-action="request.create">${serviceSelect()}${area('What would you like to achieve?','outcome','','required maxlength="4000" placeholder="For example: update our opening hours before next Monday."')}<p class="form-help">Sending a request does not approve extra charges or advertising spend.</p><div class="button-row">${submit('Send request')}${link('work','Cancel','','button secondary')}</div></form>`:empty('Your service is being set up','Your studio will add the agreed service before you send work through this space.')}</section>`;}
function workView(){return heading('A shared view','Your work','Every request keeps its scope, decisions, and updates together.',link('new','＋ Make a request','','button'))+`<section class="panel">${requestRows(rows('requests'))}</section>`;}
function requestView(id){
  const r=rows('requests').find(x=>x.id===id);if(!r)return empty('This work is unavailable','Choose a request from Your work or reload your workspace.');
  const revision=rows('revisions').find(x=>x.id===r.current_revision_id),messages=rows('messages').filter(x=>x.request_id===id);
  return link('work','← Your work','','back')+heading(engagement(r.engagement_id)?.title||'Your work',r.outcome,'Updates, scope, and decisions for this request.')+`<div class="grid two"><div><section class="panel"><div class="panel-heading"><h2>Where things stand</h2>${badge(r.state)}</div><dl class="details"><dt>Accepted scope</dt><dd>${esc(r.accepted_scope||'We’ll confirm the scope after reviewing your request.')}</dd><dt>Coverage</dt><dd>${esc(r.coverage||'Not confirmed yet')}</dd><dt>Delivery</dt><dd>${date(r.due_at)}</dd><dt>Next update</dt><dd>${dateTime(r.next_contact_at)}</dd><dt>Owner</dt><dd>${esc(name(r.owner_user_id))}</dd></dl>${r.waiting_reason?`<p class="section-note">${esc(r.waiting_reason)}</p>`:''}${revision?link('approvals',r.state==='in_review'?'Review the current work →':'View the latest version →',revision.id,'button secondary'):''}</section><section class="panel"><h2>Conversation</h2>${messagesView(messages)}<form data-action="message.send">${hidden('engagement_id',r.engagement_id)}${hidden('request_id',id)}${area('Add a message','body','','required maxlength="20000"')}${isOperator()?select('Who can see this?','visibility',[['shared','Customer and studio'],['internal','Studio only']]):hidden('visibility','shared')}${submit('Send message')}</form></section></div><div><section class="panel"><h2>Version history</h2>${rows('revisions').filter(x=>x.request_id===id).map(x=>`<div class="row"><div><strong>${link('approvals','Version '+x.sequence,x.id)}</strong><p class="muted">${esc(x.summary)}</p><span class="kicker">${date(x.created_at)}</span></div></div>`).join('')||'<p class="muted">Prepared work will appear here when it is ready to review.</p>'}</section>${isOperator()?operatorRequestForm(r):''}</div></div>`;
}
function operatorRequestForm(r){
  if(['received','triage','waiting'].includes(r.state))return `<section class="panel"><h2>Confirm the work</h2><form data-action="request.accept">${hidden('request_id',r.id)}${hidden('expected_version',r.version)}${area('Scope','scope','','required')}${field('Coverage or agreed charge','coverage','','text','required')}${field('Due','due_at','','datetime-local','required')}${field('Next update','next_contact_at','','datetime-local','required')}${select('Decision-maker','approver_id',rows('authorities').filter(x=>x.engagement_id===r.engagement_id&&!x.revoked_at).map(x=>[x.user_id,name(x.user_id)]))}${hidden('owner_id',state.user.id)}${area('Known blockers','blockers')}${submit('Accept and schedule')}</form></section>`;
  return `<section class="panel"><h2>Studio actions</h2>${link('prepare','Prepare a version',r.id,'button secondary')}<p class="form-help">Prepare exact work for customer review before execution.</p><form data-action="time.record">${hidden('engagement_id',r.engagement_id)}${hidden('request_id',r.id)}${select('Time category','category',[['delivery','Delivery'],['review','Review'],['communication','Communication'],['correction','Correction']])}${field('Minutes','minutes','','number','required min="1" max="1440"')}${submit('Record time')}</form></section>`;
}
function approvalsView(id){
  if(!id)return heading('Your decisions','Ready for your review','Approve the exact version shown, or tell us what should change.')+`<section class="panel">${requestRows(rows('requests').filter(x=>x.state==='in_review'))}</section>`;
  const rev=rows('revisions').find(x=>x.id===id);if(!rev)return empty('This version is unavailable','Open the latest version from Your work.');
  const r=rows('requests').find(x=>x.id===rev.request_id),current=r?.current_revision_id===rev.id;const decisions=rows('decisions').filter(x=>x.revision_id===id);
  const manifest=rev.manifest||{},channel=adChannel(manifest.provider||'google_ads');
  return link('work','← Back to request',rev.request_id,'back')+heading('Version '+rev.sequence,rev.summary,'Your decision applies only to this version. A later change requires another review.')+`<div class="grid two"><section class="panel"><p class="review-summary">${esc(rev.summary)}</p>${!current?'<div class="alert">A newer version exists. You can leave feedback or withdraw an earlier decision here, but you cannot approve this version.</div>':''}<dl class="details"><dt>Work</dt><dd>${esc(label(rev.kind))}</dd><dt>Cost effect</dt><dd>${esc(rev.cost_effect)}</dd><dt>Date effect</dt><dd>${esc(rev.date_effect)}</dd>${rev.kind==='campaign_package'?`<dt>Platform</dt><dd>${esc(channel?.name||manifest.provider)}</dd><dt>Ad account</dt><dd>${esc(manifest.account_id)}</dd><dt>Authorized media</dt><dd>${esc(moneyDisplay(manifest.budget_minor,manifest.currency||'USD'))}</dd>`:''}${Object.entries(manifest).filter(([k,v])=>['goal','audience','keywords','copy','headline','description','landing_page','schedule','content','scope','deliverables','acceptance','exclusions','hours'].includes(k)).map(([k,v])=>`<dt>${esc(label(k))}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl>${typeof manifest.preview_url==='string'&&/^https:\/\//.test(manifest.preview_url)?`<a class="button secondary" target="_blank" rel="noopener noreferrer" href="${esc(manifest.preview_url)}">Open the prepared preview ↗</a>`:''}<details><summary>Full version and receipt</summary><pre class="manifest">${esc(JSON.stringify(manifest,null,2))}</pre><p class="mono">${esc(rev.digest)}</p><p class="form-help">This receipt identifies the exact work, cost, and timing shown for review.</p></details></section><div><section class="panel"><h2>Your decision</h2><form data-action="decision.record">${hidden('request_id',rev.request_id)}${hidden('expected_version',r.version)}${hidden('revision_id',rev.id)}${hidden('digest',rev.digest)}${hidden('shown_scope',[rev.summary,rev.cost_effect,rev.date_effect].join(' | '))}${select('Decision','decision',[...(current&&r.state==='in_review'?[['approve','Approve this exact version']]:[]),['request_changes','Request changes'],['withdraw','Withdraw my earlier approval']])}${area('Feedback or requested changes','feedback')}<label class="checkbox-label"><input type="checkbox" name="confirmed" required>I have reviewed the work, cost, and timing above.</label>${submit('Save my decision')}</form><p class="form-help">Only your named decision-maker can approve. If needed, we’ll ask you to confirm your sign-in again.</p></section><section class="panel"><h2>Decision history</h2>${decisions.map(x=>`<div class="row"><div><strong>${esc(label(x.decision))}</strong><p>${esc(name(x.actor_id))} · ${dateTime(x.created_at)}</p>${x.feedback?`<p>${esc(x.feedback)}</p>`:''}</div></div>`).join('')||'<p class="muted">No decisions recorded for this version.</p>'}</section></div></div>`;
}
function messagesView(list){return list.length?list.map(m=>`<article class="message ${m.visibility==='internal'?'internal':''}"><div class="meta">${esc(name(m.sender_user_id))} · ${dateTime(m.created_at)}${m.visibility==='internal'?' · Studio only':''}</div><p class="body">${esc(m.body)}</p></article>`).join(''):empty('The conversation starts here','Keep questions and feedback with the work so nothing gets lost.');}
function allMessagesView(){return heading('One conversation','Messages','Messages here are shared with the studio. Approval decisions belong in the review step.')+`<div class="grid two"><section class="panel">${messagesView(rows('messages'))}</section><section class="panel"><h2>Send a message</h2><form data-action="message.send">${serviceSelect()}${area('Your message','body','','required maxlength="20000"')}${hidden('visibility','shared')}${submit('Send message')}</form></section></div>`;}
function adsView(){
  return heading('Choose the right places','Advertising','A familiar workflow for every platform. Each account keeps its own approvals, budget, and results.')+
  `<section class="panel"><div class="panel-heading"><h2>Plan → review → approve → launch → learn</h2></div><p class="muted">Approving one platform does not authorize another. A stop request stays pending until the provider’s campaign state is verified.</p></section><div class="grid">${AD_CHANNELS.map(c=>{const accounts=rows('accounts').filter(x=>x.provider===c.id);return `<section class="card"><div class="channel-icon" aria-hidden="true">${esc(c.name[0])}</div><h2>${esc(c.name)}</h2>${badge(accounts.length?accounts.every(x=>x.access_status==='verified')?'connected':'setup':'not_connected')}<p class="form-help">${esc(c.creative)}</p>${accounts.map(a=>`<div class="section-note"><strong>Account ${esc(a.account_id)}</strong><br>${esc(label(a.observed_state))} · ${dateTime(a.observed_at)}<br>${esc(label(a.environment))}</div>`).join('')}<details><summary>What’s needed</summary><ul>${c.setup.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>${accounts.length?accounts.map(a=>`<form data-action="ads.stop">${hidden('engagement_id',a.engagement_id)}${hidden('reason','Customer requested a pause from Advertising')}<button class="button danger small" type="submit">Request a stop</button></form>`).join(''):`${link('new','Ask about this channel','','button secondary small')}`}</section>`;}).join('')}</div><section class="panel"><h2>Stop requests</h2>${rows('stops').length?`<ul class="rows">${rows('stops').map(x=>`<li class="row"><div class="row-main"><strong>${esc(x.reason)}</strong><p>Requested ${dateTime(x.created_at)}${x.verified_at?' · Pause verified '+dateTime(x.verified_at):' · Provider confirmation pending'}</p></div>${badge(x.state)}</li>`).join('')}</ul>`:empty('No stop requests','When you ask to pause managed advertising, its progress and confirmation will appear here.')}</section>`;
}
function filesView(){return heading('The right files, in one place','Files','Uploads are checked before they become available for work or download.')+`<section class="panel"><form data-action="file.upload">${serviceSelect()}<label>Choose files<input type="file" name="files" multiple required accept=".png,.jpg,.jpeg,.webp,.pdf,.txt,.csv,.docx,.xlsx"><small>Up to 10 files, 20 MB each. Images, PDF, text, Word, and Excel.</small></label>${submit('Upload and check')}</form></section><section class="panel">${rows('files').length?`<ul class="rows">${rows('files').map(f=>`<li class="row"><div class="row-main"><strong>${esc(f.name)}</strong><p>${Math.ceil(f.bytes/1024)} KB · ${esc(label(f.visibility))}</p>${f.state==='ready'?`<a href="/api/files/${encodeURIComponent(f.id)}/download?business=${encodeURIComponent(org())}">Download</a>`:''}</div>${badge(f.state)}</li>`).join('')}</ul>`:empty('No files yet','Upload the files your studio needs. A received file is not usable until its checks pass.')}</section>`;}
function resultsView(){return heading('Know what changed','Results','Published reports explain the evidence, what it means, and the next decision.')+`<div class="grid two"><section class="panel"><h2>Your reports</h2>${rows('reports').length?rows('reports').map(r=>`<div class="row"><div><strong>${r.narrative_revision_id?link('approvals',r.period_key,r.narrative_revision_id):esc(r.period_key)}</strong><p>${esc(engagement(r.engagement_id)?.title)} · ${date(r.published_at)}</p></div>${badge(r.status)}</div>`).join(''):empty('Your first report is ahead','We’ll publish reviewed results once the reporting period and evidence are ready. Missing data is not shown as zero.')}</section><section class="panel"><h2>Did the inquiries lead somewhere?</h2><p class="form-help">Your outcomes help distinguish more clicks from more useful business.</p>${rows('leads').length?rows('leads').map(l=>`<form class="row" data-action="lead.save">${hidden('id',l.id)}${hidden('engagement_id',l.engagement_id)}${hidden('expected_version',l.version)}<div><strong>${esc(l.source)} · ${date(l.occurred_at)}</strong>${select('Outcome','outcome',[['unknown','Not known yet'],['suitable','Suitable inquiry'],['not_suitable','Not suitable'],['won','Became a customer'],['lost','Did not become a customer'],['existing_system','Tracked in our existing system']],l.outcome)}${submit('Save outcome')}</div></form>`).join(''):empty('No outcomes to confirm yet','When inquiries are ready for your feedback, you can update them here.')}</section></div>`;}
function businessView(){return heading('Your business, accurately represented','Business details','Keep the facts, access needs, and availability we use in your work up to date.')+`<div class="grid two"><div><section class="panel"><h2>Confirmed facts</h2>${rows('facts').map(f=>`<div class="row"><div><strong>${esc(label(f.key))}</strong><p>${esc(typeof f.value==='string'?f.value:JSON.stringify(f.value))}</p><p>Confirmed ${date(f.confirmed_at)} · ${esc(f.source)}</p></div></div>`).join('')||empty('Tell us the essentials','Confirm details such as opening hours, service area, offers, and contact information.')}</section><section class="panel"><h2>Confirm a detail</h2><form data-action="fact.confirm">${field('Detail','key','','text','required placeholder="Opening hours" maxlength="120"')}${area('Current information','value','','required')}${field('Source of this information','source','Business owner confirmation','text','required')}${submit('Confirm detail')}</form></section></div><div><section class="panel"><h2>Access we need</h2>${rows('access').map(x=>`<div class="row"><div><strong>${esc(label(x.provider))}</strong><p>${esc(x.next_action)}</p></div>${badge(x.status)}</div>`).join('')||empty('No access requests','We’ll list any accounts or permissions needed for your services here.')}</section><section class="panel"><h2>Going to be away?</h2><form data-action="absence.save">${field('Away from','starts_at','','datetime-local','required')}${field('Back on','ends_at','','datetime-local','required')}${field('Next contact','next_contact_at','','datetime-local','required')}${area('What should we know?','message','','required')}${submit('Save availability')}</form><p class="form-help">Your absence does not automatically delegate approvals or increase advertising spend.</p></section></div></div>`;}
function billingView(){return heading('Clear costs and records','Billing','Service fees and advertising media spend are separate. Payment status is confirmed from the payment provider.')+`<section class="panel"><h2>Invoices and payments</h2>${rows('payments').length?`<div class="table-wrap"><table><thead><tr><th>Record</th><th>Service</th><th>Amount</th><th>Status</th><th>Observed</th></tr></thead><tbody>${rows('payments').map(p=>`<tr><td>${esc(label(p.object_type))}</td><td>${esc(engagement(p.engagement_id)?.title)}</td><td>${esc(moneyDisplay(p.amount_minor,p.currency||'USD'))}</td><td>${badge(p.observed_state)}</td><td>${dateTime(p.observed_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No billing records to show','Billing details are available to authorized people once verified records are connected.')}</section><section class="panel"><h2>Need to end a service?</h2><p class="muted">Choose when service should end and whether managed advertising should stop or transfer. Billing, refunds, access, and exports are tracked separately.</p><form data-action="engagement.cancel" class="narrow">${serviceSelect()}${select('When should service end?','timing',[['period_end','At the end of the verified paid period'],['immediate','Immediately']])}${select('Managed advertising','exit_mode',[['stop','Stop managed campaigns'],['transfer','Arrange a verified transfer']])}${area('Reason or handoff details','reason','','required')}${submit('Request service closure')}</form></section><section class="panel"><h2>Closure progress</h2>${rows('closures').map(c=>`<div class="row"><div><strong>${esc(engagement(c.engagement_id)?.title)} · ${date(c.effective_at)}</strong><p>Service: ${esc(label(c.service_state))} · Advertising: ${esc(label(c.campaign_state))}<br>Billing: ${esc(label(c.billing_state))} · Refund: ${esc(label(c.refund_state))}<br>Export: ${esc(label(c.export_state))} · Access: ${esc(label(c.access_state))}</p></div></div>`).join('')||'<p class="muted">No services are closing.</p>'}</section>`;}
function invitationInbox(){return (state.invitations||[]).map(i=>`<section class="panel"><h2>Invitation to ${esc(i.business_name)}</h2><p>Customer role: ${esc(label(i.role))}. Accept only if this is the business you intend to join.</p><form data-action="invitation.accept">${hidden('organization_id',i.organization_id)}${hidden('id',i.id)}${hidden('business_name',i.business_name)}<label class="checkbox"><input type="checkbox" required> I recognize this business and want to join it.</label>${submit('Accept invitation')}</form></section>`).join('');}
function peopleManagement(){
 if(!state.workspace?.can_manage_people)return '';
 const roles=[['viewer','View only'],['contributor','Contributor'],['customer_admin','Business administrator']];
 return `<section class="panel"><h2>Invite a customer team member</h2><p>Invitations expire after seven days. The recipient must verify the invited email and confirm this business. Decision-making authority is assigned separately.</p><form data-action="invitation.create">${field('Email address','email','','email','required maxlength="254"')}${select('Customer role','role',roles)}${submit('Save invitation')}</form>${rows('invitations').filter(i=>!i.accepted_at&&!i.revoked_at).map(i=>`<form class="row" data-action="invitation.revoke"><div><strong>${esc(i.email)}</strong><p>${esc(label(i.role))} · expires ${date(i.expires_at)}</p>${hidden('id',i.id)}${hidden('expected_version',i.version)}${submit('Revoke invitation')}</div></form>`).join('')}</section><section class="panel"><h2>Manage customer access</h2>${rows('people').filter(p=>p.status==='active').map(p=>`<details><summary>${esc(p.name)} — ${esc(label(p.role))}</summary><form data-action="member.change">${hidden('user_id',p.id)}${hidden('expected_version',p.version)}${select('Customer role','role',roles,p.role)}${select('Access','status',[['active','Active'],['revoked','Remove access']],p.status)}${submit('Update access')}</form></details>`).join('')}<p>Removing access or changing a decision-maker to view-only ends their decision authority immediately.</p></section><section class="panel"><h2>Decision authority</h2>${rows('authorities').filter(a=>!a.revoked_at).map(a=>`<form data-action="authority.revoke"><h3>${esc(name(a.user_id))}: ${esc(label(a.domain))}</h3><p>${esc(engagement(a.engagement_id)?.title)} · ${esc(a.kind)} · expires ${date(a.ends_at)}</p>${hidden('id',a.id)}${hidden('expected_version',a.version)}${field('Reason for ending this authority','reason','','text','required')}${submit('End decision authority')}</form>`).join('')}${state.workspace.can_assign_authority?`<details><summary>Assign a verified decision-maker</summary><form data-action="authority.assign">${serviceSelect()}${select('Decision-maker','user_id',rows('people').filter(p=>p.status==='active'&&p.role!=='viewer').map(p=>[p.id,p.name]))}${select('Decision domain','domain',['contract','content','spending','finance','stop'].map(x=>[x,label(x)]))}${select('Assignment','kind',[['primary','Primary'],['substitute','Explicit substitute']])}${field('Valid from','starts_at','','datetime-local','required')}${field('Valid until','ends_at','','datetime-local','required')}${area('Independent business-authority verification evidence','evidence','','required')}${select('Replace current assignment (if applicable)','previous_id',[['','New assignment'],...rows('authorities').filter(a=>!a.revoked_at).map(a=>[a.id,name(a.user_id)+' — '+a.domain+' / '+a.kind])])}${submit('Record verified authority')}</form></details>`:'<p>Ask the studio to verify and assign new decision-makers.</p>'}</section>`;
}
function peopleView(){return heading('The right people, the right access','People & access','Workspace access and permission to approve work are separate.')+invitationInbox()+peopleManagement()+`<div class="grid two"><section class="panel"><h2>Business members</h2>${rows('people').map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><p>${esc(label(p.role))}</p></div>${badge(p.status)}</div>`).join('')}<h2>Named decision-makers</h2>${rows('authorities').filter(a=>!a.revoked_at).map(a=>`<div class="row"><div><strong>${esc(name(a.user_id))}</strong><p>${esc(label(a.domain))} · ${esc(engagement(a.engagement_id)?.title)}<br>Valid until ${date(a.ends_at)}</p></div></div>`).join('')}</section><section class="panel"><h2>Protect your sign-in</h2><p class="form-help">Studio operators must use an authenticator. Customers can add one too.</p>${state.user.factors?.length?`<form data-action="mfa.verify">${select('Authenticator','factor_id',state.user.factors.map(f=>[f.id,f.name||'Authenticator']))}${field('Six-digit code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"')}${submit('Verify authenticator')}</form>`:state.mfa?`<p>Add this setup key to your authenticator app:</p><p class="mono">${esc(state.mfa.secret)}</p><form data-action="mfa.verify">${hidden('factor_id',state.mfa.factor_id)}${field('Six-digit code','code','','text','required inputmode="numeric" pattern="[0-9]{6}"')}${submit('Finish setup')}</form>`:'<button class="button secondary" data-action="mfa.enroll">Set up an authenticator</button>'}<p class="section-note">A person’s business role never makes them a studio operator.</p></section></div>`;}
function helpView(){return heading('We’re here to make this easier','Help & preferences','Tell us when something is unclear. Keep urgent advertising controls in the Advertising section.')+`<div class="grid two"><section class="panel"><h2>What happens next?</h2><p>Send a request with the result you want. The studio checks coverage and confirms a scope, owner, delivery date, and next update.</p><p>When work is ready, review its exact version and cost. Approve it, request changes, or withdraw an earlier approval. Changes that affect your approved work need a new review.</p>${link('messages','Message the studio','','button secondary')} ${link('ads','Advertising stop controls','','button danger')}</section><section class="panel"><h2>Notifications</h2><form data-action="preference.save">${select('Digest frequency','digest',[['daily','Daily'],['weekly','Weekly'],['none','No digest']],state.workspace?.preferences?.digest||'daily')}<label class="checkbox-label"><input name="email_enabled" type="checkbox" ${state.workspace?.preferences?.email_enabled!==false?'checked':''}>Email me updates</label>${submit('Save preferences')}</form><p class="form-help">Important authority, security, and service notices follow their required delivery rules.</p></section><section class="panel"><h2>Take your records with you</h2><form data-action="export.request">${submit('Prepare my export')}</form>${rows('exports').map(x=>`<div class="row"><span>Requested ${date(x.created_at)}</span>${badge(x.state)}</div>`).join('')}</section></div>`;}
function prepareView(id){const r=rows('requests').find(x=>x.id===id);if(!r||!isOperator())return empty('Studio access required','This action is for the assigned studio team.');return heading('Prepare exact work','A new review version','The customer reviews a frozen version. Cost, timing, and platform scope are part of that version.')+`<section class="panel narrow"><form data-action="revision.create">${hidden('request_id',r.id)}${hidden('expected_version',r.version)}${select('Work type','kind',[['web_preview','Website preview'],['campaign_package','Advertising campaign'],['seo_content','SEO content'],['catalog_deliverable','Project deliverable'],['report','Results report'],['agreement','Service agreement']])}${field('Summary','summary','','text','required')}${area('Prepared work or content','content','','required')}${field('Cost effect','cost_effect','No additional service charge.','text','required')}${field('Date effect','date_effect','','text','required')}${field('Preview URL, if applicable','preview_url','','url')}<details><summary>Advertising details</summary>${select('Platform','provider',AD_CHANNELS.map(c=>[c.id,c.name]))}${field('Ad account ID','account_id')}${field('Authorized media budget (minor units, e.g. cents)','budget_minor','','number','min="1"')}${field('Currency','currency','USD','text','maxlength="3"')}${field('Goal','goal')}${area('Audience or keywords','audience')}${area('Exact ad copy','copy')}${field('Landing page','landing_page','','url')}</details>${submit('Send version for review')}</form></section>`;}
function operatorView(){if(!isOperator())return heading('Additional protection','Verify studio access','Sign in with your authenticator to see assigned studio work.')+peopleView();const data=state.workspace.operator_data||{};return heading('Studio workspace','Keep the next promise.','Prioritize waiting customers, unverified effects, and the next committed update.',link('new','New request','','button'))+`<div class="grid metrics"><section class="card"><span class="label">Incoming requests</span><strong class="metric">${rows('requests').filter(x=>['received','triage'].includes(x.state)).length}</strong></section><section class="card"><span class="label">Effects needing attention</span><strong class="metric">${(data.operations||[]).filter(x=>['unknown','failed'].includes(x.state)).length}</strong></section><section class="card"><span class="label">Evidence awaiting durable copy</span><strong class="metric">${data.receipt_backlog||0}</strong></section></div><section class="panel"><h2>Work queue</h2>${requestRows(rows('requests').filter(x=>x.state!=='complete'))}</section><div class="grid two"><section class="panel"><h2>Provider operations</h2>${(data.operations||[]).map(o=>`<div class="row"><div><strong>${esc(label(o.kind))}</strong><p>${esc(o.last_error_code?label(o.last_error_code):'Awaiting next verified step')}</p></div>${badge(o.state)}</div>`).join('')||empty('No external operations','Approved effects appear here before dispatch.')}</section><section class="panel"><h2>Service incidents</h2>${(data.incidents||[]).map(i=>`<div class="row"><div><strong>${esc(i.summary)}</strong><p>${esc(label(i.capability))} · Next update ${dateTime(i.next_update_at)}</p></div>${badge(i.status)}</div>`).join('')||empty('No open incidents','Keep verified state and the next promised update with each incident.')}</section></div>`;}
function aiView(){
  if(!isOperator())return operatorView();
  const runs=state.workspace.operator_data?.ai||[];
  return heading('Studio preparation','A useful first draft.','Every draft stays internal until a person reviews it. Your usual work tools remain available.')+`<section class="panel"><h2>Prepare from current work</h2><p>${state.workspace.business.ai_enabled?'AI preparation is enabled for this business.':'AI preparation is disabled. A business administrator can enable it in Business details.'}</p><form data-action="ai.prepare">${serviceSelect()}${select('Helper','task_type',AI_TASKS.map(x=>[x,label(x)]))}${select('Request (optional)','request_id',[['','All work for this service'],...rows('requests').map(x=>[x.id,x.outcome])])}<label class="checkbox"><input type="checkbox" name="retry_unknown"> If the previous attempt has an unknown outcome, authorize another attempt that may incur a second AI charge.</label>${submit('Prepare an internal draft')}</form><p class="form-help">OpenAI Astra receives the listed service records. No publishing, spending, or message-sending tools are connected. Generated claims still need checking.</p></section>${runs.slice().reverse().map(run=>`<section class="panel"><div class="section-heading"><h2>${esc(run.output?.title||label(run.task_type))}</h2>${badge(run.status)}</div><p>Prepared ${dateTime(run.created_at)} · ${esc(run.model_config.model)} · ${esc(run.prompt_version)}</p>${run.output?`<p class="preserve">${esc(run.output.draft)}</p>${(run.output.warnings||[]).map(x=>`<p class="alert">${esc(x)}</p>`).join('')}<ul>${(run.output.questions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><details><summary>Claims and source versions</summary>${(run.output.claims||[]).map(x=>`<p>${esc(x.text)}<small>${esc(x.source_refs.join(', '))}</small></p>`).join('')}${run.input_refs.map(x=>`<p><strong>${esc(x.ref)}</strong> · version ${esc(x.version)}</p><pre>${esc(JSON.stringify(x.data,null,2))}</pre>`).join('')}</details>`:'<p>The original records remain available. No prepared text was applied.</p>'}${run.status==='prepared'?`<form data-action="ai.review">${hidden('id',run.id)}${hidden('expected_version',run.version)}${area('Review and edit the draft','text',run.output.draft,'required maxlength="16000"')}${field('Minutes spent checking and editing','minutes','','number','required min="0" max="1440"')}${select('Your review','decision',[['accepted','Keep as reviewed internal text'],['rejected','Reject this draft']])}${submit('Save review')}</form>`:run.reviewed_text?`<h3>Reviewed text</h3><p class="preserve">${esc(run.reviewed_text)}</p>`:''}</section>`).join('')}`;
}
function aiPreference(){return state.workspace?.viewer.role==='customer_admin'?`<section class="panel"><h2>Optional AI preparation</h2><p>Allow OpenAI to prepare internal drafts from your service records. A person reviews the results. Turning this off does not interrupt your services.</p><p class="form-help">Requests use disabled response storage. Provider safety logs may be retained for up to 30 days; this is not zero data retention.</p><form data-action="ai.preference">${select('AI preparation','enabled',[['false','Disabled'],['true','Enabled']],String(Boolean(state.workspace.business.ai_enabled)))}${submit('Save AI preference')}</form></section>`:'';}
function render(){
  if(!state.user){app.innerHTML=authView();return;}
  if(!state.workspace){app.innerHTML=shell(invitationInbox()+heading('Welcome','Your workspace is taking shape.','You’re signed in. Your studio will connect your business and services to this account.')+`<section class="panel">${empty('No business access yet','An invitation must be confirmed before business records become available.')}<button class="button secondary" data-action="reload">Check again</button></section>`);return;}
  const [,section='',id]=path();let content;
  if(path()[0]==='operator')content=section==='ai'?aiView():`<p><a class="button secondary" href="${href('ai','',true)}" data-nav>Prepare with AI</a></p>`+operatorView();
  else content=section===''||section==='home'?homeView():section==='new'?newRequestView():section==='work'?(id?requestView(id):workView()):section==='approvals'?approvalsView(id):section==='messages'?allMessagesView():section==='ads'?adsView():section==='files'?filesView():section==='results'?resultsView():section==='business'?businessView():section==='billing'?billingView():section==='people'?peopleView():section==='help'?helpView():section==='prepare'?prepareView(id):empty('This page is unavailable','Choose a section from your workspace navigation.');
  if(section==='business')content+=aiPreference();
  app.innerHTML=shell(content);document.title=`${document.querySelector('h1')?.textContent||'Workspace'} — Wonder and Method`;
}
function formValues(form){const result={};for(const [key,value]of new FormData(form)){if(!(value instanceof File))result[key]=value;}for(const k of ['expected_version','minutes','budget_minor'])if(result[k]!==undefined&&result[k]!=='')result[k]=Number(result[k]);for(const k of ['due_at','next_contact_at','starts_at','ends_at'])if(result[k])result[k]=new Date(result[k]).toISOString();return result;}
async function formAction(form){
  const action=form.dataset.action,values=formValues(form);let target=null;const key=form.dataset.actionKey||(form.dataset.actionKey=crypto.randomUUID());
  if(action==='login'){const r=await api('/api/auth/start',{method:'POST',data:{email:values.email,return_path:state.returnPath}});state.csrf=r.csrf;state.loginStep='code';state.notice=r.message;return;}
  if(action==='verify'){const r=await api('/api/auth/verify',{method:'POST',data:{code:values.code}});state.csrf=r.csrf;state.user=(await api('/api/session')).user;await loadWorkspace();history.replaceState({},'',allowedReturnPath(r.return_path));return;}
  if(action==='mfa.verify'){const r=await api('/api/auth/mfa/verify',{method:'POST',data:values});state.csrf=r.csrf;state.user=(await api('/api/session')).user;state.mfa=null;await loadWorkspace();state.notice='Authenticator verified.';return;}
  delete values.confirmed;
  if(action==='request.create'){values.source='workspace';const r=await command(action,values,key);target=href('work',r.id);}
  else if(action==='invitation.accept'){const organization_id=values.organization_id;delete values.organization_id;await api('/api/command',{method:'POST',data:{organization_id,command:action,input:values},key});target=`/workspace/?business=${encodeURIComponent(organization_id)}`;}
  else if(action==='authority.assign'){if(values.previous_id)values.expected_version=rows('authorities').find(a=>a.id===values.previous_id)?.version;else delete values.previous_id;await command(action,values,key);}
  else if(action==='ai.preference'){await command(action,{enabled:values.enabled==='true'},key);}
  else if(action==='ai.prepare'){if(!values.request_id)delete values.request_id;values.retry_unknown=new FormData(form).has('retry_unknown');const result=await command(action,values,key);if(['failed','pending','unknown','stale'].includes(result.status))state.notice=result.status==='unknown'?'The prior attempt has an unknown outcome. Continue manually, or explicitly authorize another AI charge.':'No new usable draft is ready. The original records remain available.';}
  else if(action==='time.record'){values.occurred_at=new Date().toISOString();await command(action,values,key);}
  else if(action==='lead.save'){await command(action,{engagement_id:values.engagement_id,outcomes:[{id:values.id,expected_version:values.expected_version,outcome:values.outcome}]},key);}
  else if(action==='preference.save'){values.email_enabled=new FormData(form).has('email_enabled');await command(action,values,key);}
  else if(action==='fact.confirm'){const current=rows('facts').find(x=>x.key===values.key);if(current)values.expected_version=current.version;await command(action,values,key);}
  else if(action==='engagement.cancel'){values.expected_version=engagement(values.engagement_id)?.version;await command(action,values,key);}
  else if(action==='revision.create'){
    const {request_id,expected_version,kind,summary,cost_effect,date_effect,...manifest}=values;for(const k of Object.keys(manifest))if(manifest[k]==='')delete manifest[k];
    if(kind!=='campaign_package')for(const k of ['provider','account_id','budget_minor','currency','goal','audience','copy','landing_page'])delete manifest[k];
    const r=await command(action,{request_id,expected_version,kind,summary,cost_effect,date_effect,manifest},key);target=href('approvals',r.id);
  }else if(action==='file.upload'){
    const files=new FormData(form).getAll('files').filter(x=>x instanceof File&&x.size);if(files.length>10)throw new Error('Choose up to 10 files.');
    for(const file of files){if(file.size>20*1024*1024)throw new Error(`${file.name} is larger than 20 MB.`);const intent=await command('file.intent',{engagement_id:values.engagement_id,name:file.name,media_type:FILE_TYPES[file.name.split('.').at(-1).toLowerCase()]||file.type,bytes:file.size,visibility:'shared'},crypto.randomUUID());const uploaded=await fetch(`/api/files/${intent.id}/upload?business=${encodeURIComponent(org())}`,{method:'PUT',headers:{'X-CSRF-Token':state.csrf,'Content-Type':'application/octet-stream'},body:file});if(!uploaded.ok)throw new Error('The file could not be uploaded. Retry from Files.');}
  }else{if(action==='decision.record'&&values.decision==='request_changes'&&!values.feedback.trim())throw new Error('Tell us what should change.');await command(action,values,key);}
  await loadWorkspace();if(target)history.pushState({},'',target);state.notice=action==='invitation.create'?'Invitation saved. Delivery is pending; no email has been sent yet.':action==='ads.stop'?'Stop requested. Provider confirmation is still pending.':action==='decision.record'?'Your decision is recorded.':action==='file.upload'?'Files received. Their checks are now pending.':'Saved. Your workspace is up to date.';
}
document.addEventListener('submit',async event=>{
  const form=event.target.closest('form[data-action]');if(!form)return;event.preventDefault();if(state.busy)return;state.busy=true;state.error=null;state.notice=null;const button=form.querySelector('[type=submit]');if(button){button.disabled=true;button.textContent='Saving…';}
  try{await formAction(form);state.busy=false;render();document.querySelector('[role=status]')?.focus();}
  catch(error){state.busy=false;state.error=error.message;if(error.code==='sign_in'){state.returnPath=allowedReturnPath(location.pathname+location.search);state.user=null;state.loginStep='email';try{const session=await api('/api/session');state.csrf=session.csrf;}catch{}}const saved=new FormData(form);render();const replacement=document.querySelector(`form[data-action="${form.dataset.action}"]`);if(replacement)for(const [k,v]of saved){const el=replacement.elements.namedItem(k);if(el&&typeof v==='string'&&!['checkbox','file'].includes(el.type))el.value=v;}if(replacement)replacement.dataset.actionKey=form.dataset.actionKey;document.querySelector('[role=alert]')?.focus();}
});
document.addEventListener('input',event=>{const form=event.target.closest('form[data-action]');if(form)delete form.dataset.actionKey;});
document.addEventListener('change',async event=>{if(event.target.id==='business-selector'){history.pushState({},'',`/workspace/?business=${encodeURIComponent(event.target.value)}`);await reload();}});
document.addEventListener('click',async event=>{
  const nav=event.target.closest('a[data-nav]');if(nav&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();navigate(nav.getAttribute('href'));return;}
  const action=event.target.closest('[data-action]')?.dataset.action;if(!action||event.target.closest('form'))return;
  try{
    if(action==='logout'){await api('/api/auth/logout',{method:'POST',data:{}});state.user=null;state.workspace=null;state.businesses=[];state.notice=null;state.error=null;state.loginStep='email';const s=await api('/api/session');state.csrf=s.csrf;render();}
    else if(action==='restart-login'){state.loginStep='email';state.notice=null;render();}
    else if(action==='reload')await reload();
    else if(action==='mfa.enroll'){state.mfa=await api('/api/auth/mfa/enroll',{method:'POST',data:{}});render();}
  }catch(error){state.error=error.message;render();}
});
window.addEventListener('popstate',render);
async function reload(){try{await loadWorkspace();state.error=null;}catch(error){state.error=error.message;}render();}
async function start(){
  try{let session=await api('/api/session');state.csrf=session.csrf;if(!session.user&&session.refresh_available){try{const refreshed=await api('/api/auth/refresh',{method:'POST',data:{},retry:false});state.csrf=refreshed.csrf;session=await api('/api/session');}catch{}}state.user=session.user;state.returnPath=allowedReturnPath(location.pathname+location.search);if(state.user)await loadWorkspace();}
  catch(error){state.error=error.message;}render();
}
start();
